// ===== FILE: Rise 6.2.4 — Client-release2/Client/src/main/java/com/alan/clients/module/impl/exploit/LightningTracker.java =====
package com.alan.clients.module.impl.exploit;

import com.alan.clients.event.Listener;
import com.alan.clients.event.annotations.EventLink;
import com.alan.clients.event.impl.packet.PacketReceiveEvent;
import com.alan.clients.module.Module;
import com.alan.clients.module.api.Category;
import com.alan.clients.module.api.ModuleInfo;
import com.alan.clients.util.chat.ChatUtil;
import net.minecraft.network.Packet;
import net.minecraft.network.play.server.S2CPacketSpawnGlobalEntity;

@ModuleInfo(aliases = {"module.combat.lightningtracker.name"}, description = "module.exploit.lightningtracker.description", category = Category.EXPLOIT)
public class LightningTracker extends Module {

    @EventLink
    public final Listener<PacketReceiveEvent> onPacketReceiveEvent = event -> {
        final Packet<?> p = event.getPacket();

        if (p instanceof S2CPacketSpawnGlobalEntity) {
            final S2CPacketSpawnGlobalEntity wrapper = (S2CPacketSpawnGlobalEntity) p;
            final int x = (int) (Math.round((wrapper.func_149051_d() / 32.0D) * 100) / 100.0F);
            final int y = (int) (Math.round((wrapper.func_149050_e() / 32.0D) * 100) / 100.0F);
            final int z = (int) (Math.round((wrapper.func_149049_f() / 32.0D) * 100) / 100.0F);

            if (wrapper.func_149053_g() == 1) {
                ChatUtil.display("Lightning struck at " + x + ", " + y + ", " + z + " (" + (int) mc.thePlayer.getDistance(x, y, z) + " blocks away)");
            }
        }
    };
}

// NOTE (AI): The rounding (Math.round(v / 32.0 * 100) / 100.0) recovers block coordinates from the fixed-point encoding. The type guard func_149053_g() == 1 restricts output to real lightning.

